import requests
import json

def extract_deep(user_message: str, assistant_response: str) -> dict:
    prompt = f"Analyze the following conversation:\nUser: {user_message}\nAssistant: {assistant_response}\nProvide your analysis in JSON format with these fields:\n- themes (list of 1-3 word thematic labels)\n- emotional_undertone (one of [neutral, heavy, light, intense, tender, anxious, resolved])\n- spiritual_content (true/false)\n- key_concepts (up to 5 specific concepts or proper nouns worth graphing)\n- relationship_dynamic (one of [sovereign, collaborative, instructional, exploratory, null])"
    try:
        response = requests.post('http://localhost:11434/api/generate', json={
            'model': 'qwen2.5:7b',
            'prompt': prompt,
            'max_tokens': 200
        }, timeout=15)
        if response.status_code == 200:
            data = response.json()
            return json.loads(data['response'])
    except Exception as e:
        pass
    return {}
